style.css:
@-moz-document domain("roblox.com") {
body {
        background-image: url("https://pasteboard.co/nhpGpMbvyJFj.png");
        background-repeat: no-repeat;
        background-position: center center;
        background-attachment: fixed;
        background-size: cover;
        margin: 0;
        padding: 0;
    }

    .container-main, .content {
        background-color: rgb(255, 255, 255); /* Fallback for older browsers */
        background-color: rgba(255, 255, 255, 0.85); /* Semi-transparent overlay */
        border-radius: 10px;
        padding: 16px;
    }

    .rbx-header, .rbx-footer, .home-header, .game-carousel, .section-content {
        background-color: rgb(255, 255, 255); /* Fallback */
        background-color: transparent; /* Optional override */
    }
}
